H.background();
// Faraday's law:  EMF = -N dPhi/dt.  A loop of area A spins at angular speed omega
// in a field B, so flux Phi = B A cos(omega t) and EMF = N B A omega sin(omega t).
const v = H.plot2d({ xMin: -2, xMax: 12, yMin: -6, yMax: 6 });
v.grid(); v.axes({ ticks: false });
const N = Math.max(1, P.N);          // number of turns
const B = Math.max(0.05, P.B);       // field strength (T)
const A = Math.max(0.05, P.A);       // loop area (m^2)
const omega = Math.max(0.2, P.omega);// angular speed (rad/s)
const peakEMF = N * B * A * omega;   // amplitude of the induced EMF (V)
// LEFT: the rotating loop seen edge-on inside a field pointing right (+x)
const lx = 1.5, ly = 0;   // loop center (data coords)
for (let gy = -4; gy <= 4; gy += 2) {
  v.arrow(lx - 2.2, gy, lx - 0.6, gy, { color: H.colors.violet, width: 1.3, head: 5 });
}
const phase = omega * t;
// loop drawn as an ellipse whose width = projected area (cos of tilt)
const proj = Math.cos(phase);
const rw = 1.5 * Math.abs(proj) + 0.05, rh = 1.5;
const pts = [];
for (let i = 0; i <= 60; i++) { const a = i / 60 * H.TAU; pts.push([lx + rw * Math.cos(a), ly + rh * Math.sin(a)]); }
v.path(pts, { color: H.colors.accent, width: 3, close: true });
// normal vector of the loop (rotates with it); flux ∝ cos(angle between n and B)
v.arrow(lx, ly, lx + 1.6 * proj, ly + 1.6 * Math.sin(phase) * 0.4, { color: H.colors.good, width: 2.5, head: 8 });
// RIGHT: the EMF waveform scrolling, with a marker at the current value
const ax0 = 4.5, axw = 7;            // plot region for the wave (data x)
const emf = peakEMF * Math.sin(phase);
const wpts = [];
for (let i = 0; i <= 120; i++) {
  const u = i / 120;                 // 0..1 across the wave window
  const tt = phase - (1 - u) * 6;    // show the last 6 rad of history
  const yv = (peakEMF * Math.sin(tt)) / Math.max(peakEMF, 1e-6) * 4.5; // scale to ±4.5
  wpts.push([ax0 + u * axw, yv]);
}
v.line(ax0, 0, ax0 + axw, 0, { color: H.colors.axis, width: 1 });
v.path(wpts, { color: H.colors.warn, width: 2.5 });
const yNow = (emf / Math.max(peakEMF, 1e-6)) * 4.5;
v.dot(ax0 + axw, yNow, { r: 6, fill: H.colors.warn });
const flux = B * A * Math.cos(phase);
H.text("Faraday's law:  EMF = −N · dΦ/dt", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Φ = " + flux.toFixed(3) + " Wb    EMF = " + emf.toFixed(3) + " V    peak = " + peakEMF.toFixed(3) + " V", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "field B", color: H.colors.violet }, { label: "loop normal", color: H.colors.good }, { label: "induced EMF", color: H.colors.warn }], H.W - 180, 28);
